t.script:

(function() {
    try {
        var parentDoc = parent.document;
        if (!parentDoc) return;

        function getRecordId() {
            var formEl = parentDoc.querySelector('.o_form_view');
            if (formEl && formEl.dataset.recordId) {
                var id = parseInt(formEl.dataset.recordId, 10);
                if (id > 0) return id;
            }
            var pathname = parent.window.location.pathname;
            var match = pathname.match(/\/cotizacion\.express\/(\d+)/);
            if (match) return parseInt(match[1], 10);
            return 0;
        }

        var parentId = getRecordId();
        var currentId = 0;
        var currentUrlMatch = window.location.pathname.match(/\/preview_html\/(\d+)/);
        if (currentUrlMatch) {
            currentId = parseInt(currentUrlMatch[1], 10);
        }

        // Redirigir si el padre tiene ID y nosotros estamos en 0
        if (currentId === 0 && parentId > 0) {
            window.location.href = "/cotizacion/preview_html/" + parentId + "?t=" + Date.now();
            return;
        }

        // Actualizar enlace de descarga de PDF en el padre
        var pdfLink = parentDoc.getElementById('cotizacion_pdf_link');
        if (pdfLink && parentId > 0) {
            pdfLink.href = "/report/pdf/cotizaciones_express.cotizacion_preview_template/" + parentId;
        }

        // Monitorear actividad para autoguardar y actualizar
        var lastActive = Date.now();
        parentDoc.addEventListener('input', function() { lastActive = Date.now(); }, true);
        parentDoc.addEventListener('click', function() { lastActive = Date.now(); }, true);

        // Función para forzar el guardado de Odoo mediante el atajo Ctrl+S / Cmd+S
        function forceOdooSave() {
            var isMac = /Mac|iPad|iPhone|iPod/.test(parent.navigator.platform);
            var event = new KeyboardEvent('keydown', {
                bubbles: true,
                cancelable: true,
                key: 's',
                code: 'KeyS',
                keyCode: 83,
                which: 83,
                ctrlKey: !isMac,
                metaKey: isMac
            });
            parentDoc.dispatchEvent(event);
        }

        setInterval(function() {
            var activeId = getRecordId();
            if (activeId !== currentId) {
                // Cambió de ID (guardó por primera vez), redirigir
                window.location.href = "/cotizacion/preview_html/" + activeId + "?t=" + Date.now();
                return;
            }

            var formEl = parentDoc.querySelector('.o_form_view');
            var isDirty = formEl && formEl.classList.contains('o_form_dirty');

            // Si el usuario modificó datos y ha estado inactivo por más de 2 segundos,
            // forzamos el guardado del formulario en Odoo para refrescar la BD
            if (isDirty && (Date.now() - lastActive > 2000)) {
                lastActive = Date.now(); // reset timer
                forceOdooSave();
            }
        }, 1000);

        // Recarga automática cuando el formulario de Odoo se guarda
        if (parentDoc.querySelector('.o_form_view')) {
            var observer = new MutationObserver(function(mutations) {
                mutations.forEach(function(mutation) {
                    if (mutation.attributeName === 'class') {
                        var isDirtyNow = mutation.target.classList.contains('o_form_dirty');
                        if (!isDirtyNow) {
                            // El formulario se guardó en la DB, recargar vista previa tras 500ms
                            setTimeout(function() {
                                window.location.reload();
                            }, 500);
                        }
                    }
                });
            });
            observer.observe(parentDoc.querySelector('.o_form_view'), { attributes: true });
        }

    } catch (e) {
        console.error(e);
    }
})();
